<script setup>
import {useUiText} from "../ui-text";
const ui=useUiText();

import NumberControl from './NumberControl.vue';
import PanelReferenceOverlay from './PanelReferenceOverlay.vue';
import ReferenceOverlayControls from './ReferenceOverlayControls.vue';
import {computed,ref} from 'vue';import {useStudio} from '../store';import {X} from 'lucide-vue-next';import {bounds} from '../editor/geometry';import CutoutEditor from './CutoutEditor.vue';
const props=defineProps({panel:Object,page:Object});const s=useStudio();const emit=defineEmits(['close','cutout']);const cutoutOpen=ref(false),preview=ref(),imageSize=ref({w:0,h:0});const b=computed(()=>bounds(props.panel.points));let drag;
function down(e){if(e.button!==0)return;drag={x:e.clientX,y:e.clientY,imageX:props.panel.imageX||0,imageY:props.panel.imageY||0};e.currentTarget.setPointerCapture(e.pointerId);}
function move(e){if(!drag)return;if(!(e.buttons&1)){drag=null;return;}const image=preview.value.querySelector('img'),w=imageSize.value.w||b.value.w,h=imageSize.value.h||b.value.h,ratio=Math.max(b.value.w/w,b.value.h/h)*(props.panel.imageScale||1)*w/(image?.getBoundingClientRect().width||preview.value.clientWidth);props.panel.imageX=drag.imageX+(e.clientX-drag.x)*ratio;props.panel.imageY=drag.imageY+(e.clientY-drag.y)*ratio;}
function reset(){Object.assign(props.panel,{imageScale:1,imageX:0,imageY:0,imageRotation:0});}
</script>
<template><div class="modal-backdrop" @click.self="emit('close')"><section class="modal panel-image-editor" role="dialog" :aria-label="ui(&quot;分镜图片编辑&quot;)"><div class="modal-dismiss-row"><button class="icon-button" :aria-label="ui(&quot;关闭图片编辑面板&quot;)" @click="emit('close')"><X/></button></div><div class="modal-title"><div><h2>{{ui("分镜图片 · 取景与破框")}}</h2><p>{{ui("直接拖动画面调整取景，修改实时保存。")}}</p></div></div><div class="panel-image-columns" v-resize-panels="{key:'panel-image',config:s.config,min:[260,220]}"><div ref="preview" class="panel-image-preview" v-preview-zoom="{target:'.panel-image-raw'}" @pointerdown="down" @pointermove="move" @pointerup="drag=null" @pointercancel="drag=null"><div class="panel-image-raw"><img :src="panel.image" :alt="ui(&quot;分镜完整原图&quot;)" @load="imageSize={w:$event.target.naturalWidth,h:$event.target.naturalHeight}"/><PanelReferenceOverlay v-if="page&&s.config.previewReference?.enabled!==false" :page="page" :panel="panel" :width="imageSize.w" :height="imageSize.h" :opacity="s.config.previewReference?.opacity??.35"/></div></div><aside class="image-transform-inspector"><h3>{{ui("取景调整")}}</h3><ReferenceOverlayControls v-if="page"/><p class="muted">{{ui("拖动画面，或精细调整偏移与角度。")}}</p><label>{{ui("图片缩放")}}<input type="range" v-model.number="panel.imageScale" min=".1" max="6" step=".02"/></label><div class="property-grid"><label>{{ui("水平偏移")}}<NumberControl v-model="panel.imageX" :label="ui(&quot;水平偏移&quot;)" unit="px"/></label><label>{{ui("垂直偏移")}}<NumberControl v-model="panel.imageY" :label="ui(&quot;垂直偏移&quot;)" unit="px"/></label></div><label>{{ui("旋转角度")}}<NumberControl v-model="panel.imageRotation" :label="ui(&quot;图片旋转角度&quot;)" :min="-180" :max="180" unit="°"/></label><div class="transform-shortcuts"><button @click="panel.imageRotation=Math.max(-180,(panel.imageRotation||0)-90)">↶ 90°</button><button @click="panel.imageX=0;panel.imageY=0">{{ui("居中")}}</button><button @click="panel.imageRotation=Math.min(180,(panel.imageRotation||0)+90)">90° ↷</button></div><button class="secondary reset-framing" @click="reset">{{ui("恢复默认取景")}}</button><div class="image-cutout-action"><h3>{{ui("让角色走出分镜")}}</h3><p>{{ui("自动抠出人物；也可涂抹选择人物或物品，生成可移动的透明图层。")}}</p><button class="primary" @click="cutoutOpen=true">{{ui("智能抠图与破框")}}</button></div><button class="secondary" @click="emit('close')">{{ui("完成调整")}}</button></aside></div></section><CutoutEditor v-if="cutoutOpen" :image="panel.image" :image-id="panel.imageId" :page="page" :panel="panel" @close="cutoutOpen=false" @done="emit('cutout',$event)"/></div></template>
